2	   FIXED 16:9 STAGE: MANDATORY BASE STYLES
3	   Include this ENTIRE file in every presentation.
4	   Slides are authored at 1920×1080 and scaled as a whole.
5	   =========================================== */
6	
7	/* 1. Lock the browser viewport */
8	html,
9	body {
10	    width: 100%;
11	    height: 100%;
12	    margin: 0;
13	    overflow: hidden;
14	    background: var(--stage-bg, #000);
15	}
16	
17	/* 2. Full-window deck viewport */
18	.deck-viewport {
19	    position: fixed;
20	    inset: 0;
21	    overflow: hidden;
22	    background: var(--stage-bg, #000);
23	}
24	
25	/* 3. Fixed 16:9 design canvas.
26	   JavaScript sets transform: translate(...) scale(...). */
27	.deck-stage {
28	    position: absolute;
29	    left: 0;
30	    top: 0;
31	    width: 1920px;
32	    height: 1080px;
33	    overflow: hidden;
34	    transform-origin: 0 0;
35	    background: var(--slide-bg, #fff);
36	}
37	
38	/* 4. Slides stack inside the fixed stage.
39	   Content must be laid out at 1920×1080, not reflowed per device. */
40	.slide {
41	    position: absolute;
42	    inset: 0;
43	    width: 1920px;
44	    height: 1080px;
45	    overflow: hidden;
46	    display: block;
47	    visibility: hidden;
48	    opacity: 0;
49	    pointer-events: none;
50	    background: var(--slide-bg, #fff);
51	}
52	
53	.slide.active,
54	.slide.visible {
55	    visibility: visible;
56	    opacity: 1;
57	    pointer-events: auto;
58	    z-index: 1;
59	}
60	
61	/* 5. Keep media inside authored slide bounds */
62	img,
63	video,
64	canvas,
65	svg {
66	    max-width: 100%;
67	    max-height: 100%;
68	}
69	
70	/* 6. Presentation chrome stays outside the slide design system */
71	.deck-controls {
72	    position: fixed;
73	    left: 50%;
74	    bottom: 22px;
75	    transform: translateX(-50%);
76	    z-index: 1000;
77	}
78	
