  <div class="hero-code">五步法深度分析 &middot; LW-01</div>
  <div class="hero-badge-wrap">
    <div class="hero-badge" style="background:{bg};box-shadow:0 4px 24px {shadow};">
      <span class="num">{lw01_total}</span>
      <span class="unit">总分</span>
    </div>
  </div>
